_LOCK = threading.RLock()
_LANG = 'vi'
_CACHE = {'vi': _VI, 'en': _EN}

def get_lang() -> str:
    with _LOCK:
        return _LANG

def set_lang(code: str) -> None:
    """Đặt ngôn ngữ hiện tại: 'vi' hoặc 'en'."""
    global _LANG
    code = (code or 'vi').lower()
    with _LOCK:
        if code in _CACHE:
            _LANG = code

def t(key: str) -> str:
    """Dịch khóa tĩnh. Khi vi: trả về key (tiếng Việt). Khi en: trả về bản dịch tiếng Anh."""
    with _LOCK:
        if _LANG == 'vi':
            return key
        return _EN.get(key, key)

def tf(template: str, *args, **kwargs) -> str:
    """Dịch template rồi format. Khi vi: format key gốc. Khi en: format bản dịch."""
    with _LOCK:
        if _LANG == 'vi':
            tpl = template
        else:
            tpl = _EN.get(template, template)
    try:
        return tpl.format(*args, **kwargs)
    except Exception:
        return template.format(*args, **kwargs) if args or kwargs else template

def available_languages() -> list[str]:
    return list(_CACHE.keys())